const array = [1, 3, 5, 8, 13];
const target = 8;

function binarySearch(values, searchTarget) {
  let left = 0;
  let right = values.length - 1;

  while (left <= right) {
    const middle = Math.floor((left + right) / 2);

    if (values[middle] === searchTarget) return middle;

    if (values[middle] < searchTarget) {
      left = middle + 1;
    } else {
      right = middle - 1;
    }
  }

  return -1;
}

