function largestRectangleArea(indices, values) {
  let bestArea = 0;

  for (let index = 1; index <= values.length; index++) {
    const currentHeight = index === values.length ? 0 : values[index];

    while (
      indices.length > 0 &&
      currentHeight < values[indices.at(-1)]
