function maxSlidingWindow(indices, input, size) {
  const result = [];

  for (let index = 1; index < input.length; index++) {
    while (indices.length > 0 && indices[0] <= index - size) {
      indices.shift();
    }

    while (indices.length > 0) {
      const previousIndex = indices.pop();
      if (input[previousIndex] > input[index]) {
        indices.push(previousIndex);
        break;
      }
    }

    indices.push(index);

    if (index >= size - 1) {
      result.push(input[indices[0]]);
    }
  }

  while (indices.length > 0) indices.shift();
  return result;
}

