function orangesRotting(values, matrix) {
  let fresh = 0;

  for (let row = 0; row < matrix.length; row++) {
    for (let column = 0; column < matrix[row].length; column++) {
      if (matrix[row][column] === 1) fresh++;
    }
  }

  const directions = [
    [1, 0],
    [-1, 0],
    [0, 1],
    [0, -1]
  ];
  let minutes = 0;

  while (values.length > 0 && fresh > 0) {
    const levelSize = values.length;

    for (let index = 0; index < levelSize; index++) {
      const position = values.shift();
      const row = Math.floor(position / matrix[0].length);
      const column = position % matrix[0].length;

      for (const [rowOffset, columnOffset] of directions) {
        const nextRow = row + rowOffset;
        const nextColumn = column + columnOffset;

        if (
          nextRow >= 0 &&
          nextRow < matrix.length &&
          nextColumn >= 0 &&
          nextColumn < matrix[0].length &&
          matrix[nextRow][nextColumn] === 1
        ) {
          matrix[nextRow][nextColumn] = 2;
          fresh--;
          const nextPosition = nextRow * matrix[0].length + nextColumn;
          values.push(nextPosition);
        }
      }
    }

    minutes++;
  }

  while (values.length > 0) values.shift();
  return fresh === 0 ? minutes : -1;
}

