function mergeTwoLists(first, second) {
  const dummy = { value: 0, next: null };
  let tail = dummy;
  let left = first;
  let right = second;

  while (left !== null && right !== null) {
    if (left.value <= right.value) {
      tail.next = left;
      left = left.next;
    } else {
      tail.next = right;
      right = right.next;
    }
    tail = tail.next;
  }

  tail.next = left === null ? right : left;
  return dummy.next;
}

