function groupAnagrams(groupsByKey, input) {
  const groups = [];

  for (const word of input) {
    const key = [...word].sort().join('');
    let groupIndex = groupsByKey.get(key);

    if (groupIndex === undefined) {
      groupIndex = groups.length;
      groups.push([]);
      groupsByKey.set(key, groupIndex);
    }

    groups[groupIndex].push(word);
  }

  return groups;
}

